adjustSynchronization(currentTime: number) {
    if (this.speechQueue.length > 0) {
        const nextSpeechTime = this.speechQueue[0].startTime;
        const timeDifference = nextSpeechTime - currentTime;

        if (this.dubbingMode === 'advanced') {
            const maxSpeed = parseFloat(this.maxSpeedControl.value);

            if (timeDifference < 500) { 
                // Dublagem atrasada: Acelerar tudo ao máximo permitido
                this.speedControl.value = maxSpeed;
                if (this.speakingControlMode === 'slowDown') {
                    this.video.playbackRate = Math.min(this.video.playbackRate + 0.1, 0.2);
                }
            } else if (timeDifference > 1000) { 
                // Dublagem adiantada: Reduzir velocidade da voz para acompanhar
                this.speedControl.value = 1.2;
                if (this.speakingControlMode === 'slowDown') {
                    this.video.playbackRate = Math.max(this.video.playbackRate - 0.1, 1.0);
                }
            } else { 
                // Sincronizada perfeita: Retornar à configuração do usuário
                this.speedControl.value = this.userConfiguredSpeed;
                if (this.speakingControlMode === 'slowDown') {
                    this.video.playbackRate = 1.0;
                }
            }
            this.updateRangeValue('speed');
        }
    }
}
```

