adjustSynchronization(currentTime: number) {
    if (this.speechQueue.length > 0) {
        const targetSpeed = this.calculateTargetSpeed(currentTime);

        // Lógica simples de interpolação linear (Lerp) para suavizar a mudança
        const currentSpeed = this.speedControl.value;
        const alpha = 0.1; // Fator de suavização (quanto menor, mais lento a transição)
        this.speedControl.value += (targetSpeed - currentSpeed) * alpha;

        if (this.dubbingMode === 'advanced') {
            const videoCurrentRate = this.video.playbackRate;
            let targetVideoRate = 1.0;

            if (this.speakingControlMode === 'slowDown') {
                targetVideoRate = 0.85; 
            } else if (this.speakingControlMode === 'speedUp') {
                targetVideoRate = 1.15;
            }

            // Aplica suavemente também a velocidade do vídeo
            this.video.playbackRate += (targetVideoRate - videoCurrentRate) * alpha;

            this.updateRangeValue('speed');
        }
    }
}

// Helper calcula qual velocidade deve ser usada baseado no desvio de tempo
private calculateTargetSpeed(currentTime: number): number {
    const nextSpeechTime = this.speechQueue[0].startTime;
    const diff = nextSpeechTime - currentTime;

    if (diff < 500) return parseFloat(this.maxSpeedControl.value); // Urgente
    if (diff > 1000) return 1.2; // Demorado
    return this.userConfiguredSpeed;
}
