            // Áudio chegou antes do esperado: Tocar vídeo em loop rápido ou acelerar
            voiceSpeed = parseFloat(this.maxSpeedControl.value);
            videoSpeedFactor = 2.0; 
        } else if (diff < 500) {
            // Áudio chegando atrasado: Acelerar moderadamente
