            videoSpeedFactor = 1.1;
        } else if (diff > 1000) {
            // Áudio demorando muito: Fazer vídeo ficar mais lento para esperar
            voiceSpeed = 0.9;
            videoSpeedFactor = 0.8;
        }

        this.speedControl.value = voiceSpeed;
        this.video.playbackRate = this.video.playbackRate * videoSpeedFactor;

        this.updateRangeValue('speed');
    }
}
