adjustSynchronization(currentTime: number) {
    if (this.speechQueue.length === 0) return;

    const nextSpeechTime = this.speechQueue[0].startTime;
    const diff = nextSpeechTime - currentTime;
    const minBufferTime = 300; // Tempo mínimo para considerar estável

    if (diff < minBufferTime && this.dubbingMode === 'advanced') {
        // Se o buffer está crítico, forçar máxima velocidade imediatamente
        this.speedControl.value = parseFloat(this.maxSpeedControl.value);
        this.video.playbackRate = 0.2; // Forçar alta velocidade do vídeo

        this.updateRangeValue('speed');
        return;
    }

    // Se estável, aplicar ajustes suaves
    if (diff > 1000) {
